use mockito :: { Mock , Server , ServerGuard } ; use regex :: Regex ; impl MockServer { pub async fn new () -> Self { let server = Server :: new_async () . await ; Self { server } } pub async fn mock_models (& mut self , body : serde_json :: Value , status : usize) -> Mock { self . server . mock ("GET" , "/models") . with_status (status) . with_header ("content-type" , "application/json") . with_body (body . to_string ()) . create_async () . await } pub fn url (& self) -> String { self . server . url () } # [doc = " Mock any POST path returning the given status code and JSON body with"] # [doc = " `Content-Type: application/json`.  Used to simulate a provider API"] # [doc = " returning a non-2xx error so the SSE client fires `InvalidStatusCode`."] pub async fn mock_post_error (& mut self , path : & str , body : & str , status : usize) -> Mock { self . server . mock ("POST" , path) . with_status (status) . with_header ("content-type" , "application/json") . with_body (body) . create_async () . await } # [doc = " Mock any POST path returning 200 with `Content-Type: application/json`"] # [doc = " (not `text/event-stream`).  Used to simulate an `InvalidContentType`"] # [doc = " error from the SSE client."] pub async fn mock_post_wrong_content_type (& mut self , path : & str , body : & str) -> Mock { self . server . mock ("POST" , path) . with_status (200) . with_header ("content-type" , "application/json") . with_body (body) . create_async () . await } pub async fn mock_responses_stream (& mut self , events : Vec < String > , status : usize) -> Mock { let sse_body = events . join ("\n\n") ; self . server . mock ("POST" , "/v1/responses") . with_status (status) . with_header ("content-type" , "text/event-stream") . with_header ("cache-control" , "no-cache") . with_body (sse_body) . create_async () . await } # [doc = " Mock SSE responses without `Content-Type: text/event-stream`."] # [doc = " Simulates the Codex backend behavior where SSE data is returned"] # [doc = " as `application/octet-stream` instead of `text/event-stream`."] pub async fn mock_codex_responses_stream (& mut self , path : & str , events : Vec < String > , status : usize ,) -> Mock { let sse_body = events . join ("\n\n") ; self . server . mock ("POST" , path) . with_status (status) . with_header ("content-type" , "application/octet-stream") . with_header ("cache-control" , "no-cache") . with_body (sse_body) . create_async () . await } pub async fn mock_google_chat_stream (& mut self , model : & str , events : Vec < String > , status : usize ,) -> Mock { let mut sse_body = events . join ("\n\n") ; sse_body . push_str ("\n\n") ; let path = format ! ("/models/{}:streamGenerateContent" , model) ; self . server . mock ("POST" , path . as_str ()) . match_query (mockito :: Matcher :: UrlEncoded ("alt" . into () , "sse" . into ())) . with_status (status) . with_header ("content-type" , "text/event-stream") . with_header ("cache-control" , "no-cache") . with_body (sse_body) . create_async () . await } }